{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Rule 3745-52-15 is titled 'Satellite accumulation area requirements for small quantity generators and large quantity generators' and provides administrative section heading context without establishing standalone substantive duties."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "A generator is permitted to accumulate up to 55 gallons of non-acute hazardous waste and either 1 quart of liquid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 or 1 kilogram (2.2 pounds) of solid acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 in containers at or near any point of generation where wastes initially accumulate under the control of the process operator, without a permit or permit by rule and without complying with Chapters 3745-50, 3745-54 to 3745-57, 3745-205, 3745-65 to 3745-69, 3745-256, 3745-266, and 3745-267 of the Administrative Code, provided that all conditions for exemption in this rule are met."
    },
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "alternative",
      "meaning": "A generator may comply with the conditions for exemption in rule 3745-52-15 instead of complying with the conditions for exemption in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, except as required in paragraphs (A)(7) and (A)(8) of rule 3745-52-15."
    },
    {
      "quote_ref": "F002",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, if a container holding hazardous waste is not in good condition or begins to leak, the generator must immediately transfer the hazardous waste to a container that is in good condition and does not leak, or immediately transfer and manage the waste in a central accumulation area operated in compliance with paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code."
    },
    {
      "quote_ref": "F003",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, the generator must use a container made of or lined with materials that will not react with, and are otherwise compatible with, the hazardous waste to be accumulated, so that the container's ability to contain the waste is not impaired."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F001"],
      "kind": "background",
      "meaning": "Paragraph (A)(3) provides the subhead 'Special standards for incompatible wastes' and serves as structural topic framing without containing independent substantive mandates."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F001"],
      "kind": "prohibition",
      "meaning": "As a condition for exemption for satellite accumulation, incompatible wastes, or incompatible wastes and materials, must not be placed in the same container, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F001"],
      "kind": "prohibition",
      "meaning": "As a condition for exemption for satellite accumulation, hazardous waste must not be placed in an unwashed container that previously held an incompatible waste or material, unless paragraph (B) of rule 3745-65-17 of the Administrative Code is complied with."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a container holding hazardous waste that is incompatible with any waste or other materials accumulated nearby in other containers must be separated from the other materials or protected from the incompatible waste or material by any practical means."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a container holding hazardous waste must be kept closed at all times during accumulation, subject only to specified exceptions in paragraphs (A)(4)(a) and (A)(4)(b)."
    },
    {
      "quote_ref": "F009",
      "scope_refs": ["F001", "F008"],
      "kind": "exception",
      "meaning": "A container holding hazardous waste during satellite accumulation is not required to be closed when adding, removing, or consolidating waste."
    },
    {
      "quote_ref": "F010:F011",
      "scope_refs": ["F001", "F008"],
      "kind": "exception",
      "meaning": "A container holding hazardous waste during satellite accumulation is not required to be closed when temporary venting of the container is necessary for the proper operation of equipment."
    },
    {
      "quote_ref": "F010:F012",
      "scope_refs": ["F001", "F008"],
      "kind": "exception",
      "meaning": "A container holding hazardous waste during satellite accumulation is not required to be closed when temporary venting of the container is necessary to prevent dangerous situations, such as the build-up of extreme pressure."
    },
    {
      "quote_ref": "F013:F014",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a generator must mark or label the container with the words 'Hazardous Waste'."
    },
    {
      "quote_ref": "F013:F015",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "As a condition for exemption for satellite accumulation, a generator must mark or label the container with an indication of the hazards of the contents, which may include applicable hazardous waste characteristics (ignitable, corrosive, reactive, toxic), DOT hazard communication under 49 CFR Part 172 subpart E or F, OSHA hazard statements or pictograms under 29 CFR 1910.1200, or NFPA code 704 chemical hazard labels."
    },
    {
      "quote_ref": "F016:F017",
      "scope_refs": ["F001"],
      "kind": "alternative",
      "meaning": "A generator accumulating acute hazardous waste listed in rule 3745-51-31 or paragraph (E) of rule 3745-51-33 or non-acute hazardous waste in excess of satellite accumulation limits at or near any point of generation must, within three consecutive calendar days, comply with the applicable central accumulation area requirements in paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code, as an alternative to removing the excess."
    },
    {
      "quote_ref": "F016:F019",
      "scope_refs": ["F001"],
      "kind": "alternative",
      "meaning": "A generator accumulating acute or non-acute hazardous waste in excess of satellite accumulation limits at or near any point of generation may remove the excess from the satellite accumulation area within three consecutive calendar days to a central accumulation area operated in compliance with paragraph (B) of rule 3745-52-16 or paragraph (A) of rule 3745-52-17 of the Administrative Code."
    },
    {
      "quote_ref": "F016:F020",
      "scope_refs": ["F001", "F018"],
      "kind": "alternative",
      "meaning": "A generator accumulating acute or non-acute hazardous waste in excess of satellite accumulation limits at or near any point of generation may remove the excess from the satellite accumulation area within three consecutive calendar days to an on-site permit by rule or permitted treatment, storage, or disposal facility."
    },
    {
      "quote_ref": "F016:F021",
      "scope_refs": ["F001", "F018"],
      "kind": "alternative",
      "meaning": "A generator accumulating acute or non-acute hazardous waste in excess of satellite accumulation limits at or near any point of generation may remove the excess from the satellite accumulation area within three consecutive calendar days to an off-site designated facility."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F001", "F016"],
      "kind": "requirement",
      "meaning": "During the three-consecutive-calendar-day period following accumulation in excess of satellite limits, the generator must continue complying with paragraphs (A)(1) to (A)(5) of this rule and must mark or label the containers holding the excess accumulation with the date the excess amount began accumulating."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "All satellite accumulation areas operated by a small quantity generator must meet the preparedness and prevention requirements of paragraph (B)(8) of rule 3745-52-16 of the Administrative Code and the emergency procedures of paragraph (B)(9) of rule 3745-52-16 of the Administrative Code."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F001"],
      "kind": "requirement",
      "meaning": "All satellite accumulation areas operated by a large quantity generator must meet the preparedness, prevention, and emergency procedures set forth in rules 3745-52-250 to 3745-52-265 of the Administrative Code."
    },
    {
      "quote_ref": "F025",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Paragraph (B) is designated '[Reserved.]' and contains no substantive legal requirements or regulatory provisions."
    },
    {
      "quote_ref": "F026",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The comment directs the reader to rule 3745-50-11 of the Administrative Code titled 'Incorporated by reference' for dates of referenced non-regulatory government publications, publications of recognized organizations and associations, federal rules, and federal statutory provisions."
    }
  ]
}
